// Title: Dot Slicer
// Author: Claude, ItsWesSmithYo
// Project: OneManShYo

void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
    // Normalize and center coordinates
    vec2 uv = (2.0 * fragCoord - iResolution.xy) / min(iResolution.x, iResolution.y);

    // Initialize base color with oscillating background
    float background = 0.5 + 0.5 * sin(iTime * 0.5);
    vec3 col = vec3(background);

    // Constants for the pattern
    const float NUM_PAIRS = 7.0;
    const float NUM_SPOKES = 3.0;
    const float BASE_RADIUS = 0.5;

    // Light direction for shading
    vec3 lightDir = normalize(vec3(1.0, 1.0, 1.0));

    // Store sphere data for depth sorting
    struct SphereData {
        vec2 pos;
        float radius;
        float phase;
        float zOffset;
        float scale;
    };
    SphereData spheres[28]; // Both outer and inner spheres
    int sphereCount = 0;

    // Calculate sphere positions and properties first
    for(float i = 0.0; i < NUM_PAIRS; i++) {
        float angle = iTime + i * 2.0 * 3.14159 / NUM_PAIRS;
        float undulation = 0.1 * sin(iTime * 2.0 + i);
        vec2 offset = vec2(cos(angle), sin(angle)) * (BASE_RADIUS + undulation);
        float phase = 0.5 + 0.5 * sin(iTime + i);

        // Calculate z-offset based on rotation
        float zOffset = 0.5 * sin(angle * 2.0 + iTime * 1.5);
        float perspectiveScale = 1.0 / (1.0 + zOffset);

        // Store outer sphere
        spheres[sphereCount].pos = offset;
        spheres[sphereCount].radius = 0.1 * perspectiveScale;
        spheres[sphereCount].phase = 1.0 - phase;
        spheres[sphereCount].zOffset = zOffset;
        spheres[sphereCount].scale = perspectiveScale;
        sphereCount++;

        // Store inner sphere
        spheres[sphereCount].pos = offset * 0.6;
        spheres[sphereCount].radius = 0.06 * perspectiveScale;
        spheres[sphereCount].phase = phase;
        spheres[sphereCount].zOffset = zOffset;
        spheres[sphereCount].scale = perspectiveScale;
        sphereCount++;
    }

    // Draw far spheres first (smaller ones)
    for(int i = 0; i < sphereCount; i++) {
        if(spheres[i].scale < 0.8) { // Draw if far away
            vec2 pos = spheres[i].pos;
            float d = length(uv - pos) - spheres[i].radius;
            float sphere = smoothstep(0.01, 0.0, d);

            vec3 spherePos = vec3(pos, spheres[i].zOffset + 
                                sqrt(max(0.0, spheres[i].radius*spheres[i].radius - d*d)));
            vec3 sphereNormal = normalize(vec3(uv - pos, spherePos.z));
            float sphereShade = 0.2 + 0.8 * max(0.0, dot(sphereNormal, lightDir));

            col = mix(col, vec3(spheres[i].phase) * sphereShade, sphere * step(d, 0.0));
        }
    }

    // Draw the rotating tubular spokes
    for(float i = 0.0; i < NUM_SPOKES; i++) {
        float angle = -iTime * 0.5 + i * 2.0 * 3.14159 / NUM_SPOKES;
        float phase = 0.5 + 0.5 * sin(iTime * 0.7 + i);
        vec2 dir = vec2(cos(angle), sin(angle));

        vec2 spokeStart = vec2(0.0);
        vec2 spokeEnd = dir * 0.8;
        vec2 pa = uv - spokeStart;
        vec2 ba = spokeEnd - spokeStart;
        float h = clamp(dot(pa,ba)/dot(ba,ba), 0.0, 1.0);
        float spoke = length(pa - ba*h) - 0.05;

        vec2 radialDir = normalize(pa - ba*h);
        vec3 spokeNormal = normalize(vec3(radialDir, 0.0));

        float spokeMask = smoothstep(0.01, 0.0, spoke);
        float spokeShade = 0.2 + 0.8 * max(0.0, dot(spokeNormal, lightDir));
        col = mix(col, vec3(phase) * spokeShade, spokeMask);
    }

    // Draw near spheres last (larger ones)
    for(int i = 0; i < sphereCount; i++) {
        if(spheres[i].scale >= 0.8) { // Draw if close
            vec2 pos = spheres[i].pos;
            float d = length(uv - pos) - spheres[i].radius;
            float sphere = smoothstep(0.01, 0.0, d);

            vec3 spherePos = vec3(pos, spheres[i].zOffset + 
                                sqrt(max(0.0, spheres[i].radius*spheres[i].radius - d*d)));
            vec3 sphereNormal = normalize(vec3(uv - pos, spherePos.z));
            float sphereShade = 0.2 + 0.8 * max(0.0, dot(sphereNormal, lightDir));

            col = mix(col, vec3(spheres[i].phase) * sphereShade, sphere * step(d, 0.0));
        }
    }

    fragColor = vec4(col, 1.0);
}
